def retry(times):
    def deco(func):
        def wrapper():
            for attempt in range(1, times + 1):
                try:
                    return func()
                except ValueError:
                    print("попытка", attempt, "не удалась")
            return "сдаюсь"
        return wrapper
    return deco

calls = 0

@retry(3)
def flaky():
    global calls
    calls += 1
    if calls < 3:
        raise ValueError
    return "успех"

print(flaky())

